def solve():
    import sys
    s = sys.stdin.readline().strip()
    n = len(s)
    res = 0
    for i in range(n):
        cnt1 = 0
        for j in range(i, n):
            if s[j] == '1':
                cnt1 += 1
            if cnt1 > 0 and (j - i + 1) % cnt1 == 0:
                res += 1
    print(res)

solve()
